#!/usr/bin/env python3
"""Browser checks of trap placement, combat and persistence in a controlled arena."""
import json
import sys
from pathlib import Path
from playwright.sync_api import sync_playwright
out=Path('docs/screenshots/traps'); checks={}; errors=[]
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox','--enable-unsafe-swiftshader','--use-angle=swiftshader','--disable-dev-shm-usage'])
 page=b.new_page(viewport={'width':1280,'height':720}); page.on('pageerror',lambda e:errors.append(str(e)))
 try:
  page.goto(sys.argv[1] if len(sys.argv)>1 else 'http://127.0.0.1:5173/',wait_until='domcontentloaded');page.locator('#newgame').wait_for(state='visible',timeout=120000);page.click('#newgame');page.wait_for_function('game.started && document.pointerLockElement===game.canvas',timeout=60000)
  page.evaluate('''() => {let g=game,w=g.world,p=g.player.pos;g.renderer.setAnimationLoop(null);let X=Math.floor(p.x),Z=Math.floor(p.z),Y=Math.floor(p.y)+6;w.generateAround(X,Z,3);for(let x=X-10;x<=X+10;x++)for(let z=Z-10;z<=Z+10;z++){w.set(x,Y-1,z,1);for(let y=Y;y<Y+6;y++)w.set(x,y,z,0)}w.rebuildAround(X,Z,2);p.set(X+.5,Y,Z-4.5);g.player.vel.set(0,0,0);window.site={X,Y,Z};g.entities.enemies.forEach(e=>e.dead=true);g.entities.enemies=[];Object.assign(g.inv,{spikeTrap:3,trapdoor:3,arrowTrap:4,flameTrap:4,blastMine:2,ammo:50,goo:50})}''')
  checks.update(page.evaluate('''() => {const g=game,w=g.world,{X:x,Y:y,Z:z}=site,c={};let before=g.inv.spikeTrap;c.noChargeOnInvalid=!g.traps.place('spikes',0,x,y+1,z)&&g.inv.spikeTrap===before;c.placeSpike=g.traps.place('spikes',0,x,y,z);let e=g.entities.spawnEnemy('zombie',x+.5,y,z+.5), hp=e.hp,php=g.player.hp;g.traps.update(0);c.pausedNoDamage=e.hp===hp;g.traps.update(.01);c.spikeDamage=e.hp<hp&&g.player.hp===php;e.dead=true;g.traps.restore([]);return c}'''))
  checks.update(page.evaluate('''() => {const g=game,w=g.world,{X:x,Y:y,Z:z}=site,c={};w.set(x,y-1,z,0);w.set(x+1,y,z,1);c.hatchPlace=g.traps.place('trapdoor',0,x,y,z);g.player.pos.set(x+.5,y,z-2);g.player.aimDir.set(0,-.2,1).normalize();let t=g.traps.traps[0];c.closedSolid=w.get(x,y,z)===8;g.traps.interact();c.openAir=t.open&&w.get(x,y,z)===0;let e=g.entities.spawnEnemy('zombie',x+.5,y+1,z+.5);e.vel.set(0,0,0);for(let i=0;i<20;i++)e.physics(.05);c.falls=e.pos.y<y+.5;e.pos.set(x+.5,y,z+.5);g.traps.interact();c.closeBlocked=t.open; e.dead=true;g.traps.interact();c.closeSolid=!t.open&&w.get(x,y,z)===8;let s=g.traps.snapshot();g.traps.restore(s);c.restoreClosed=g.traps.traps.length===1&&!g.traps.traps[0].open;g.traps.restore([]);w.set(x,y,z,0);w.set(x,y-1,z,1);w.set(x+1,y,z,0);return c}'''))
  checks.update(page.evaluate('''() => {const g=game,w=g.world,{X:x,Y:y,Z:z}=site,c={};g.entities.enemies=[];g.traps.place('flame',0,x,y,z);let t=g.traps.traps[0],e=g.entities.spawnEnemy('zombie',x+.5,y,z-3.5),hp=e.hp;g.traps.update(.1);c.behindSafe=e.hp===hp&&t.ammo===30;e.pos.set(x+4.5,y,z+.5);g.traps.update(.1);c.sideSafe=e.hp===hp;e.pos.set(x+.5,y,z+4.5);w.set(x,y,z+2,1);g.traps.update(.1);c.wallBlocks=e.hp===hp;w.set(x,y,z+2,0);g.traps.update(.1);c.flameHitsAndVisible=e.hp<hp&&t.ammo===29&&g.traps.flames.length>0;let s=g.traps.snapshot();g.traps.restore(s);c.ammoPersist=g.traps.traps[0].ammo===29;e.dead=true;g.traps.restore([]);return c}'''))
  checks.update(page.evaluate('''() => {const g=game,w=g.world,{X:x,Y:y,Z:z}=site,c={};g.entities.enemies=[];g.traps.place('arrow',0,x,y,z);let t=g.traps.traps[0],e=g.entities.spawnEnemy('zombie',x+.5,y,z+4.5),hp=e.hp;g.traps.update(.1);c.arrowFired=t.ammo===19&&g.projectiles.list.some(p=>p.hostilesOnly);for(let i=0;i<20;i++)g.projectiles.update(.01);c.arrowHits=e.hp<hp;e.dead=true;g.traps.restore([]);return c}'''))
  checks.update(page.evaluate('''() => {const g=game,w=g.world,{X:x,Y:y,Z:z}=site,c={};g.entities.enemies=[];let animal=g.entities.spawnEnemy('zombie',x+.5,y,z+2.5);g.entities.enemies=[];g.foraging.wildlife.push(animal);let hp=animal.hp;w.set(x,y,z+4,12);let origin=g.player.pos.clone().set(x+.5,y+.7,z+.5),dir=origin.clone().set(0,0,1);g.projectiles.bullet(origin,dir,{dmg:50,blockDmg:0,owner:g.player,hostilesOnly:true});for(let i=0;i<20;i++)g.projectiles.update(.01);c.wildlifeSafe=animal.hp===hp;c.tntSafe=w.get(x,y,z+4)===12;g.foraging.wildlife.pop();animal.dead=true;w.set(x,y,z+4,0);return c}'''))
  page.evaluate('''() => {const g=game,{X:x,Y:y,Z:z}=site;g.inv.flameTrap++;g.traps.place('flame',0,x,y,z);g.entities.enemies=[];g.entities.spawnEnemy('zombie',x+.5,y,z+4.5);g.traps.update(.1);g.time=.5;g.updateDay(0);g.camera.position.set(x+5,y+5,z-5);g.camera.lookAt(x+.5,y+.5,z+2);g.camera.updateMatrixWorld();g.renderer.render(g.scene,g.camera)}''');page.screenshot(path=str(out/'01-flame.jpg'),type='jpeg',quality=90)
 except Exception as e: errors.append(str(e))
 finally:
  (out/'results.json').write_text(json.dumps({'checks':checks,'errors':errors},indent=2)+'\n');b.close()
print(checks,errors)
if errors or not all(checks.values()): raise SystemExit(1)
